"""``other`` cases: values from an independent implementation (R meta), generated by ``r/other_software.R`` and committed; no test runs R."""

import pytest

import correctness.cases


@pytest.mark.parametrize('case', correctness.cases.case_params('other'))
# auditme: accept[paired-sibling-helpers] one test module per kind of evidence, as the spec lays out the suite
def test_other_software(case: correctness.cases.Case) -> None:
    correctness.cases.check_case(case, correctness.cases.run_case(case))
